/**
 * Push notifications (Web Push: lock screen and Notification Centre on iPhone from iOS 16.4 when Folio is
 * opened from the Home Screen; Android and desktop browsers too).
 *
 *  - Signing keys (VAPID) are generated by the server the first time they're needed and kept in the
 *    database, the private key encrypted with FOLIO_SECRET. Nothing to configure.
 *  - Every alert has a key (e.g. "budget-80:2026-11") recorded in notify_log, so it is never sent twice.
 *  - Quiet hours, 11 pm to 7 am on each device's own clock: alerts wait in push_queue for the morning run.
 *  - Event alerts (spending, budget, money in, low balance) are checked when transactions arrive; date
 *    alerts (scholarship, card due, daily summary, investments) by the daily run, and the weekly recap
 *    on Sunday evening (vercel.json "crons").
 *
 * The wording is conversational and approved by the owner; every figure comes from the person's own
 * records, and comparisons are only ever with their own history.
 */
import webpush from "web-push";
import { all, get, run, now } from "../db.js";
import { decrypt, encrypt } from "../crypto.js";
import { notifyPrefs, type NotifyPrefs, type User } from "../auth.js";
import { formatMoney } from "../../shared/money.js";
import { incomeSummary, monthSummary, spending, thisMonth, today } from "./summary.js";
import { series } from "./market.js";

export interface Push { title: string; body: string; url?: string; tag?: string }
type Kind = keyof NotifyPrefs;

// ---- keys
let keys: { publicKey: string; privateKey: string } | null = null;
export async function vapidKeys() {
  if (keys) return keys;
  const row = await get<{ value: string }>("SELECT value FROM app_settings WHERE key = 'vapid'");
  if (row) {
    const v = JSON.parse(row.value);
    keys = { publicKey: v.publicKey, privateKey: decrypt(v.privateKeyEnc)! };
    return keys;
  }
  const k = webpush.generateVAPIDKeys();
  // ON CONFLICT: if two instances race, both read back the same stored pair.
  await run("INSERT INTO app_settings(key, value) VALUES ('vapid', ?) ON CONFLICT (key) DO NOTHING",
    JSON.stringify({ publicKey: k.publicKey, privateKeyEnc: encrypt(k.privateKey) }));
  return vapidKeys();
}

// ---- sending
type Sub = { endpoint: string; keys: { p256dh: string; auth: string } };
type Sender = (sub: Sub, payload: string) => Promise<void>;
let sender: Sender | null = null;
let clock: () => Date = () => new Date();
/** Tests swap in a fake sender and clock. */
export function setPushSender(fn: Sender | null) { sender = fn; }
export function setPushClock(fn: (() => Date) | null) { clock = fn ?? (() => new Date()); }
async function defaultSender(): Promise<Sender> {
  const k = await vapidKeys();
  const subject = process.env.PUSH_SUBJECT ?? "https://folio-ivory-six.vercel.app";
  return (sub, payload) => webpush.sendNotification(sub, payload, { vapidDetails: { subject, publicKey: k.publicKey, privateKey: k.privateKey }, TTL: 60 * 60 * 24, urgency: "normal" }).then(() => {});
}

/** 11 pm to 7 am on the device's own clock (unknown time zone: never quiet). */
export function isQuiet(tz: string | null | undefined, at = clock()): boolean {
  if (!tz) return false;
  try {
    const h = Number(new Intl.DateTimeFormat("en-GB", { hour: "numeric", hourCycle: "h23", timeZone: tz }).format(at));
    return h >= 23 || h < 7;
  } catch { return false; }
}

async function deliver(subRow: { id: number; endpoint: string; p256dh: string; auth: string }, payload: string): Promise<boolean> {
  const send = sender ?? (await defaultSender());
  try { await send({ endpoint: subRow.endpoint, keys: { p256dh: subRow.p256dh, auth: subRow.auth } }, payload); return true; }
  catch (e: any) {
    // The device unsubscribed or the subscription expired: forget it.
    if (e?.statusCode === 404 || e?.statusCode === 410) await run("DELETE FROM push_subs WHERE id = ?", subRow.id);
    return false;
  }
}

/**
 * Sends to every device the person turned notifications on for, once per key. During a device's quiet
 * hours the alert waits for the morning run instead. Returns how many devices got it (or will).
 */
export async function notify(user: User, kind: Kind | "test", key: string, push: Push): Promise<number> {
  if (kind !== "test" && !notifyPrefs(user.notify)[kind]) return 0;
  const subs = await all<{ id: number; endpoint: string; p256dh: string; auth: string; tz: string | null }>("SELECT * FROM push_subs WHERE user_id = ?", user.id);
  if (!subs.length) return 0;
  if (kind !== "test") {
    // Claim the key first: a concurrent run can't send the same alert.
    const claimed = await run("INSERT INTO notify_log(user_id, key, sent_at) VALUES (?,?,?) ON CONFLICT DO NOTHING", user.id, key, now());
    if (!claimed.changes) return 0;
  }
  const payload = JSON.stringify({ title: push.title, body: push.body, url: push.url ?? "/", tag: push.tag ?? key, accent: user.accent ?? "folio" });
  const quietOk = kind !== "test" && notifyPrefs(user.notify).quiet;
  let reached = 0;
  for (const s of subs) {
    if (quietOk && isQuiet(s.tz)) { await run("INSERT INTO push_queue(sub_id, payload, created_at) VALUES (?,?,?)", s.id, payload, now()); reached++; continue; }
    if (await deliver(s, payload)) reached++;
  }
  return reached;
}

/** Sends what waited through quiet hours, for devices whose morning has come. */
export async function flushQueue() {
  const rows = await all<{ id: number; sub_id: number; payload: string; endpoint: string; p256dh: string; auth: string; tz: string | null }>(
    "SELECT q.id, q.sub_id, q.payload, s.endpoint, s.p256dh, s.auth, s.tz FROM push_queue q JOIN push_subs s ON s.id = q.sub_id ORDER BY q.id");
  let sent = 0;
  for (const r of rows) {
    if (isQuiet(r.tz)) continue;
    await deliver({ id: r.sub_id, endpoint: r.endpoint, p256dh: r.p256dh, auth: r.auth }, r.payload);
    await run("DELETE FROM push_queue WHERE id = ?", r.id);
    sent++;
  }
  return sent;
}

// ---- wording helpers
const money = (minor: number, ccy: string) => formatMoney(Math.round(minor), ccy).replace(/\.00$/, "");
const DAY = 864e5;
const iso = (ms: number) => new Date(ms).toISOString().slice(0, 10);
const shortDate = (d: string) => new Date(`${d}T00:00:00Z`).toLocaleDateString("en-GB", { day: "numeric", month: "short", timeZone: "UTC" });
const monthName = (m: string) => new Date(`${m}-01T00:00:00Z`).toLocaleDateString("en-GB", { month: "long", timeZone: "UTC" });
const firstName = (u: User) => u.name.trim().split(/\s+/)[0];
const bankShort = (bank: string | null | undefined) => (bank ?? "").replace(/\s+(Bank|Bank Ltd\.?|Limited)$/i, "").trim();
const andList = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);
/** "today", "tomorrow", a weekday within the week, or a date. */
function when(dayIso: string, from: string) {
  const n = Math.round((Date.parse(dayIso) - Date.parse(from)) / DAY);
  if (n <= 0) return "today";
  if (n === 1) return "tomorrow";
  if (n < 7) return new Date(`${dayIso}T00:00:00Z`).toLocaleDateString("en-GB", { weekday: "long", timeZone: "UTC" });
  return `on ${shortDate(dayIso)}`;
}
/** "JASSO" from "JASSO Monbukagakusho Honors Scholarship (MEXT)"; otherwise the name as entered. */
const shortSource = (name: string) => { const w = name.trim().split(/\s+/)[0]; return /^[A-Z0-9]{2,8}$/.test(w) ? w : name; };
/** Average daily spending over the 30 days before `day` (0 if there's none). */
async function usualDay(user: User, day: string) {
  const t = Date.parse(day);
  const s = await spending(user, iso(t - 30 * DAY), iso(t - DAY));
  return s.total > 0 ? s.total / 30 : 0;
}
const spanOf = (days: number) => (days >= 10 ? `about ${Math.round(days / 7)} weeks` : `about ${Math.max(1, Math.round(days))} days`);

// ---- event alerts
export interface Fresh { merchant: string; merchantKey?: string; amountMinor: number; currency: string; type: string; date?: string; bank?: string | null; last4?: string | null; category?: string | null; wallet?: string | null }

/** After new transactions arrive: what was spent (automatic imports only), money in, then the budget. */
export async function afterTransactions(user: User, fresh: Fresh[], automatic: boolean) {
  if (automatic) {
    const spent = fresh.filter((t) => t.type === "expense");
    if (spent.length === 1) {
      const t = spent[0];
      const n = t.merchantKey ? (await get<{ n: number }>("SELECT COUNT(*) n FROM transactions WHERE user_id = ? AND merchant_key = ?", user.id, t.merchantKey))!.n : 2;
      const card = t.bank || t.last4 ? `${bankShort(t.bank)}${t.last4 ? ` ••${t.last4}` : ""}`.trim() : "";
      const cat = (t.category ?? "").split(" / ")[0];
      await notify(user, "transactions", `txn:${Date.now()}`, {
        title: `Spent ${money(t.amountMinor, t.currency)} at ${t.merchant}`,
        body: n <= 1 && cat && cat !== "Uncategorised" ? `First time there. I put it under ${cat}.` : card || "New transaction",
        url: "/#activity",
      });
    } else if (spent.length > 1) {
      const ccy = spent[0].currency;
      const places = [...new Set(spent.map((t) => t.merchant))];
      const total = spent.filter((t) => t.currency === ccy).reduce((a, t) => a + t.amountMinor, 0);
      await notify(user, "transactions", `txn:${Date.now()}`, places.length === 1
        ? { title: `Spent ${money(total, ccy)} at ${places[0]}`, body: `${spent.length} purchases`, url: "/#activity" }
        : { title: `Spent ${money(total, ccy)} across ${places.length} places`, body: andList(places.slice(0, 3)) + (places.length > 3 ? " and more" : ""), url: "/#activity" });
    }
    for (const t of fresh.filter((x) => x.type === "transfer" && x.wallet)) {
      await notify(user, "transactions", `move:${Date.now()}:${t.wallet}`, t.wallet === "Cash"
        ? { title: `Took out ${money(t.amountMinor, t.currency)} in cash`, body: "Not counted as spending", url: "/#activity" }
        : { title: `Topped up ${money(t.amountMinor, t.currency)} on ${t.wallet}`, body: "Not counted as spending", url: "/#activity" });
    }
    // Money in that matches an expected payment: say so, and let the person confirm it.
    const income = fresh.filter((t) => t.type === "income");
    if (income.length) {
      const sources = (await incomeSummary(user)).sources;
      for (const t of income) for (const src of sources) {
        const p = src.payments.find((x: any) => x.outstandingMinor > 0 && src.currency === t.currency && x.outstandingMinor === t.amountMinor && x.expectedDate
          && Math.abs(Date.parse(x.expectedDate) - Date.parse(t.date ?? today())) <= 10 * DAY);
        if (p) await notify(user, "scholarship", `income-in:${p.id}`, { title: `${shortSource(src.name)} just came in 💸`, body: `${money(t.amountMinor, t.currency)} arrived. Tap to mark it received.`, url: "/#plan" });
      }
    }
  }
  const refund = fresh.find((t) => t.type === "refund");
  await budgetCheck(user, refund?.merchant);
  await lowBalanceCheck(user);
}

/** Budget: spending fast mid-month, at the alert level, over, and back under after a refund (each once a month). */
export async function budgetCheck(user: User, refundMerchant?: string) {
  if (user.monthly_budget_minor == null) return;
  const s = await monthSummary(user, thisMonth());
  if (!s.budget) return;
  const m = s.month, cur = s.currency;
  if (s.spent > s.budget) {
    await notify(user, "budget", `budget-over:${m}`, { title: "You've gone over budget", body: `You're ${money(s.spent - s.budget, cur)} over for ${monthName(m)}. No stress, it resets on the 1st.`, url: "/#plan" });
    return;
  }
  if (await get("SELECT 1 FROM notify_log WHERE user_id = ? AND key = ?", user.id, `budget-over:${m}`))
    await notify(user, "budget", `budget-under:${m}`, { title: "Nice, you're back under budget 🎉", body: `${refundMerchant ? `That ${refundMerchant} refund did it. ` : ""}You're ${money(s.budget - s.spent, cur)} under now.`, url: "/#plan" });
  const left = s.budget - s.spent, days = Math.max(1, s.daysInMonth - s.daysElapsed);
  if (s.pctUsed != null && s.pctUsed >= user.alert_threshold)
    await notify(user, "budget", `budget-${user.alert_threshold}:${m}`, { title: `Hey ${firstName(user)}, you've used ${s.pctUsed}% of your budget`, body: `You've got ${money(left, cur)} left for ${days} day${days === 1 ? "" : "s"}. That's about ${money(left / days, cur)} a day.`, url: "/#plan" });
  else if (s.projected != null && s.daysElapsed >= 8 && s.daysElapsed <= s.daysInMonth - 5 && s.projected > s.budget * 1.05)
    await notify(user, "budget", `budget-pace:${m}`, { title: "You're spending a bit fast this month", body: `At this rate you'll end up around ${money(s.projected, cur)}, about ${money(s.projected - s.budget, cur)} over. Easing up a little this week would sort it.`, url: "/#plan" });
}

/** A prepaid or forex card with about five days or less left at the person's usual pace on it. */
export async function lowBalanceCheck(user: User) {
  for (const a of await all<any>("SELECT * FROM accounts WHERE user_id = ? AND kind = 'card' AND balance_minor IS NOT NULL AND balance_minor > 0", user.id)) {
    if (!/prepaid|forex/i.test(a.card_type ?? "")) continue;
    const since = iso(Date.parse(today()) - 21 * DAY);
    const r = (await get<{ s: number | null }>("SELECT SUM(amount_minor) s FROM transactions WHERE user_id = ? AND account_id = ? AND type = 'expense' AND currency = ? AND date >= ?", user.id, a.id, a.currency, since))!;
    const perDay = (Number(r.s) || 0) / 21;
    if (perDay <= 0) continue;
    const days = a.balance_minor / perDay;
    if (days > 5) continue;
    const isForex = /forex/i.test(a.card_type ?? "");
    await notify(user, "card", `low:${a.id}:${String(a.balance_as_of ?? "").slice(0, 10)}`, {
      title: `Your ${isForex ? "forex" : "prepaid"} card is getting low`,
      body: `${money(a.balance_minor, a.currency)} left on ${bankShort(a.bank) || a.name}. That's about ${Math.max(1, Math.round(days))} day${Math.round(days) === 1 ? "" : "s"} at your usual pace.`, url: "/",
    });
  }
}

// ---- date alerts (morning run)
export async function dailyChecks(user: User, day = today()): Promise<string[]> {
  const sent: string[] = [];
  const t = Date.parse(day);
  const usual = await usualDay(user, day);

  // Scholarship and other income: due within two days, or late (once each)
  const income = await incomeSummary(user);
  for (const src of income.sources) {
    const name = shortSource(src.name), scholarship = src.kind === "scholarship";
    for (const p of src.payments) {
      if (!p.expectedDate || p.outstandingMinor <= 0) continue;
      const inDays = Math.round((Date.parse(p.expectedDate) - t) / DAY);
      if (inDays >= 0 && inDays <= 2) {
        const lands = inDays === 0 ? "lands today" : inDays === 1 ? "lands tomorrow" : `lands in ${inDays} days`;
        const covers = usual > 0 && src.currency === user.base_currency ? ` That's ${spanOf(p.outstandingMinor / usual)} of spending sorted.` : "";
        if (await notify(user, "scholarship", `income-soon:${p.id}`, { title: scholarship ? `Your ${name} money ${lands}` : `${name} ${lands}`, body: `${money(p.outstandingMinor, src.currency)} on ${shortDate(p.expectedDate)}.${covers}`, url: "/#plan" }))
          sent.push(`income-soon:${p.id}`);
      }
      if (inDays < 0 && inDays >= -14 && (await notify(user, "scholarship", `income-late:${p.id}`,
        { title: `Still waiting on ${name}`, body: `The ${money(p.outstandingMinor, src.currency)} was due on ${shortDate(p.expectedDate)}. Got it already? Tap to mark it received.`, url: "/#plan" })))
        sent.push(`income-late:${p.id}`);
    }
  }

  // Credit cards: the bill is due within three days (from the due day set on the card)
  for (const a of await all<any>("SELECT * FROM accounts WHERE user_id = ? AND due_day IS NOT NULL", user.id)) {
    const d = new Date(`${day}T00:00:00Z`);
    const clamp = (y: number, m: number, dd: number) => new Date(Date.UTC(y, m, Math.min(dd, new Date(Date.UTC(y, m + 1, 0)).getUTCDate())));
    let due = clamp(d.getUTCFullYear(), d.getUTCMonth(), a.due_day);
    if (due.getTime() < t) due = clamp(d.getUTCFullYear(), d.getUTCMonth() + 1, a.due_day);
    const inDays = Math.round((due.getTime() - t) / DAY), dueIso = iso(due.getTime());
    if (inDays > 3) continue;
    // Spending in the cycle this bill covers: the statement before the due date, back to the one before it.
    let cycle = "";
    if (a.statement_day) {
      let end = clamp(due.getUTCFullYear(), due.getUTCMonth(), a.statement_day);
      if (end.getTime() >= due.getTime()) end = clamp(due.getUTCFullYear(), due.getUTCMonth() - 1, a.statement_day);
      const start = clamp(end.getUTCFullYear(), end.getUTCMonth() - 1, a.statement_day).getTime() + DAY;
      const r = (await get<{ s: number | null }>("SELECT SUM(CASE WHEN type = 'refund' THEN -amount_minor ELSE amount_minor END) s FROM transactions WHERE user_id = ? AND account_id = ? AND type IN ('expense','refund') AND currency = ? AND date >= ? AND date <= ?",
        user.id, a.id, a.currency, iso(start), iso(end.getTime())))!;
      if (Number(r.s) > 0) cycle = `You've spent ${money(Number(r.s), a.currency)} on it this cycle. `;
    }
    if (await notify(user, "card", `card-due:${a.id}:${dueIso}`, {
      title: `Your ${bankShort(a.bank) || a.name} card bill is due ${when(dueIso, day)}`,
      body: `${cycle}Pay by ${shortDate(dueIso)} to skip the interest.`, url: "/",
    })) sent.push(`card-due:${a.id}`);
  }

  await lowBalanceCheck(user);

  // Daily summary: yesterday, in one of three moods
  const yesterday = iso(t - DAY);
  const y = await spending(user, yesterday, yesterday);
  const s = await monthSummary(user, thisMonth());
  const cur = user.base_currency;
  const left = s.budget != null ? (s.remaining! >= 0 ? `${money(s.remaining!, cur)} left for ${y.total > 0 ? "the month" : monthName(s.month)}.` : `${money(-s.remaining!, cur)} over budget this month.`) : "";
  const top = y.merchants[0]?.name;
  let daily: Push;
  if (y.total <= 0) daily = { title: "You didn't spend anything yesterday 👏", body: left || "Nice and quiet." };
  else if (usual > 0 && y.total >= usual * 2.5) daily = { title: "Yesterday was a big one", body: `You spent ${money(y.total, cur)}, about ${Math.round(y.total / usual)}× your usual.${top ? ` Mostly at ${top}.` : ""}` };
  else daily = { title: `Morning, ${firstName(user)} ☀️`, body: `You spent ${money(y.total, cur)} yesterday${top ? `, mostly at ${top}` : ""}.${left ? ` ${left}` : ` ${money(s.spent, cur)} so far this month.`}` };
  if (await notify(user, "daily", `daily:${day}`, { ...daily, url: "/" })) sent.push(`daily:${day}`);

  // Investments: a holding that moved 4% or more at the latest close (at most two a day)
  if (notifyPrefs(user.notify).investing) sent.push(...await investmentMoves(user, day));

  // A missed event check (e.g. spending entered by hand) is caught here too.
  await budgetCheck(user);
  return sent;
}

async function investmentMoves(user: User, day: string): Promise<string[]> {
  const holdings = await all<{ symbol: string; quantity: number; currency: string }>("SELECT symbol, quantity, currency FROM holdings WHERE user_id = ?", user.id);
  const key = decrypt(user.av_key_enc);
  const moves: { sym: string; pct: number; gain: number; ccy: string; qty: number; date: string }[] = [];
  for (const h of holdings) {
    let pts: { date: string; close: number }[] = [];
    try {
      // Saved prices when fresh enough; otherwise one cached request (12-hour cache, paced).
      if (key) pts = (await series(key, h.symbol)).data.points;
      else { const row = await get<{ payload: string }>("SELECT payload FROM market_cache WHERE key = ?", `series:${h.symbol}`); pts = row ? JSON.parse(row.payload).points : []; }
    } catch { continue; }
    if (pts.length < 2) continue;
    const a = pts[pts.length - 1], b = pts[pts.length - 2];
    const pct = ((a.close - b.close) / b.close) * 100;
    if (Math.abs(pct) >= 4) moves.push({ sym: h.symbol.split(".")[0], pct, gain: h.quantity * (a.close - b.close), ccy: h.currency, qty: h.quantity, date: a.date });
  }
  const sent: string[] = [];
  for (const mv of moves.sort((x, y) => Math.abs(y.pct) - Math.abs(x.pct)).slice(0, 2)) {
    const up = mv.pct >= 0, shares = `Your ${mv.qty} share${mv.qty === 1 ? "" : "s"}`;
    const k = `move:${mv.sym}:${mv.date}`;
    if (await notify(user, "investing", k, {
      title: `${mv.sym} is ${up ? "up" : "down"} ${Math.abs(mv.pct).toFixed(1)}%${mv.date === day ? " today" : ""}`,
      body: `${shares} ${up ? "made" : "lost"} ${formatMoney(Math.round(Math.abs(mv.gain) * 100), mv.ccy).replace(/\.00$/, "")}.`, url: "/#invest",
    })) sent.push(k);
  }
  return sent;
}

/** Sunday evening: the week's spending against the week before, and where most of it went. */
export async function weeklyRecap(user: User, day = today()) {
  const t = Date.parse(day);
  const week = await spending(user, iso(t - 6 * DAY), day), before = await spending(user, iso(t - 13 * DAY), iso(t - 7 * DAY));
  if (week.total <= 0 && before.total <= 0) return false;
  const cur = user.base_currency;
  const cats = await all<{ id: number; name: string }>("SELECT id, name FROM categories WHERE user_id = ?", user.id);
  const topCat = [...week.byCategory].sort((a, b) => b[1] - a[1])[0];
  const topName = topCat ? cats.find((c) => c.id === topCat[0])?.name.split(" / ")[0].toLowerCase() : null;
  const pct = before.total > 0 ? Math.round(((week.total - before.total) / before.total) * 100) : null;
  const vs = pct == null ? "" : Math.abs(pct) < 5 ? "About the same as last week." : `That's ${Math.abs(pct)}% ${pct < 0 ? "less" : "more"} than last week.`;
  return (await notify(user, "weekly", `weekly:${day}`, {
    title: `You spent ${money(week.total, cur)} this week`,
    body: [vs, topName && topName !== "uncategorised" ? `Most of it went on ${topName}.` : ""].filter(Boolean).join(" ") || "Here's your week.", url: "/#plan",
  })) > 0;
}

/** The scheduled runs: "daily" each morning, "weekly" on Sunday evening. Queued quiet-hours alerts go out first. */
export async function scheduledRun(kind: "daily" | "weekly" = "daily") {
  const queued = await flushQueue();
  const users = await all<User>("SELECT u.* FROM users u WHERE EXISTS (SELECT 1 FROM push_subs s WHERE s.user_id = u.id)");
  let sent = 0;
  for (const u of users) {
    try { sent += kind === "weekly" ? ((await weeklyRecap(u)) ? 1 : 0) : (await dailyChecks(u)).length; }
    catch { /* one person's failure doesn't stop the rest */ }
  }
  // Keep the log small: alerts older than 120 days can't recur.
  await run("DELETE FROM notify_log WHERE sent_at < ?", new Date(Date.now() - 120 * DAY).toISOString());
  return { kind, users: users.length, sent, queued };
}
/** Kept for the daily schedule's original name. */
export const dailyRun = () => scheduledRun("daily");
